        AND PH.SupplyQty > 0


ORDER BY LP.ProdSeq

    LIMIT #{topCnt}


    LIMIT #{startNum}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tStrLayoutProdApply LP
INNER JOIN shopion.tPrdProd PH ON LP.ProdCode = PH.ProdCode


