    ProdSeq = #{prodSeq},
    Remark = #{remark},
    State = #{state},
    ChangeDate = #{changeDate},
    ChangeId = #{changeId},
    ChangeName = #{changeName}
WHERE DesignId = #{designId}
  AND LayoutCode = #{layoutCode}
  AND ChnlCode = #{chnlCode}
  AND ProdCode = #{prodCode}

